    derive: (i, deep) => {
      const p = (deep && deep.params) || {};
      const growth = p.growth || 1, peak = p.peak || 1, interval = p.interval || 30;
      const U = i.dau * 1e6 * growth, C = (U * i.conc) / 100, upd = C / interval, fan = (i.friends * i.online) / 100, subs = (i.friends * i.app) / 100;
      const push = upd * fan, memGB = (U * subs * 20) / 1e9;
      return {
        k: peak, peak, growth, interval, U, C, upd, fan, subs, push, friends: i.friends, memGB,
        psCpu: push / PUSH_PER_PS, psMem: Math.max(1, Math.ceil(memGB / PS_MEM_GB)), cacheGB: (C * peak * 100) / 1e9,
        conn: C / SESSION, rest: (U * 5) / DAY, totalSubs: C * subs,
      };
    },

